INSERT INTO "public"."Movies" ("id", "Title", "Synopsis", "Reviews", "TrailerURL", "TrailerPicLink", "MPAA_US_Film_Rating", "isRunning", "isComingSoon", "Poster_img_URL") VALUES ('1', 'Barbie', 'Barbie and Ken leave the perfection of Barbie Land when Barbie starts questioning her reality, embarking on a hilarious and heartfelt adventure in the real world that challenges ideas of identity and purpose.', '6.8', 'https://www.youtube.com/watch?v=pBk4NYhWNMM', 'https://i.ytimg.com/vi/R97vOlMD7q8/maxresdefault.jpg', 'PG-13', 'false', 'true', 'https://i.ebayimg.com/images/g/Cd0AAOSwocdkoDER/s-l1200.jpg'), ('2', 'Inception', 'Dom Cobb is a skilled thief who enters people’s dreams to steal secrets. When offered a chance at redemption, he must pull off the impossible: planting an idea instead of stealing one. As the mission unfolds, dream and reality blur in a breathtakingly complex heist.', '8.8', 'https://www.youtube.com/watch?v=YoHD9XEInc0', 'https://i.ytimg.com/vi/-F7s8aEndQs/maxresdefault.jpg', 'PG-13', 'true', 'false', 'https://www.originalfilmart.com/cdn/shop/files/inception_2010_advance_original_film_art_f4801a23-edb3-4db0-b382-1e2aec1dc927_5000x.jpg?v=1715962948'), ('3', 'Interstellar', 'In a future where Earth is dying, ex-pilot Cooper joins a mission to travel through a wormhole in search of a new habitable world for humanity. As time and space distort, he must choose between saving humanity and seeing his children again.', '8.7', 'https://www.youtube.com/watch?v=zSWdZVtXT7E', 'https://i.ytimg.com/vi/Lm8p5rlrSkY/maxresdefault.jpg', 'PG-13', 'true', 'false', 'https://filmartgallery.com/cdn/shop/files/Interstellar-Vintage-Movie-Poster-Original_ab1cfab0.jpg'), ('4', 'Oppenheimer', 'A deep-look into the life of J. Robert Oppenheimer, the theoretical physicist who helped develop the first nuclear weapons, balancing scientific triumph with moral consequences amid the pressures of global war.', '8.3', 'https://www.youtube.com/watch?v=uYPbbksJxIg', 'https://i.ytimg.com/vi/bK6ldnjE3Y0/maxresdefault.jpg', 'R', 'false', 'true', 'https://m.media-amazon.com/images/I/71FSrzTqHSL.jpg'), ('5', 'Passages', 'A same-sex male couple’s marriage is put to crisis when one of them begins an affair with a young woman, bringing complications, emotional conflict, and questions about love and identity.', '9.4', 'https://www.youtube.com/watch?v=m5Kr38lovJc', 'https://i.ytimg.com/vi/bZex1Bg_uwo/maxresdefault.jpg', 'R', 'false', 'true', 'https://m.media-amazon.com/images/M/MV5BNDA0NzhkNGYtNmZhYy00NTlmLTk4NDAtMDlkMjc5Njc2NmFjXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg'), ('6', 'Sinners', 'Set in 1932 in the Mississippi Delta, twin criminal brothers return to their hometown and are forced to confront a supernatural evil. The film blends horror, music, and period atmosphere in a genre-defying story.', '9.7', 'https://www.youtube.com/watch?v=bKGxHflevuk', 'https://i.ebayimg.com/images/g/01kAAOSwtexoBgql/s-l1200.jpg', 'R', 'true', 'false', 'https://i.ebayimg.com/images/g/01kAAOSwtexoBgql/s-l1200.jpg'), ('7', 'The Actor', 'Based on Donald E. Westlake’s novel Memory, The Actor finds Paul Cole (André Holland) stranded in a strange small town with no memory of who he is or how he ended up there. He starts to rebuild a life, including a relationship with Edna (Gemma Chan), while fragments of his past surface—but it’s unclear what parts of his identity are real and what are illusions.', '6', 'https://www.youtube.com/watch?v=Q4cf6DqIYl4', 'https://m.media-amazon.com/images/M/MV5BNTk1NDY4ZjYtZTBkZS00MjQzLThmOWItNGIwNjJjYjdhODMzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', 'R', 'false', 'true', 'https://m.media-amazon.com/images/I/61DCEg5XJ1L._UF894,1000_QL80_.jpg'), ('8', 'The Creator', 'In a future war between humans and artificial intelligence, a former soldier is tasked with finding and destroying a weapon that could end humanity, only to discover the weapon is an AI child.', '6.8', 'https://www.youtube.com/watch?v=ex3C1-5Dhb8', 'https://m.media-amazon.com/images/I/61DCEg5XJ1L._UF894,1000_QL80_.jpg', 'PG-13', 'false', 'true', 'https://m.media-amazon.com/images/I/713kiC-8JhL.jpg'), ('9', 'The Grand Budapest Hotel', 'In the 1930s, at a famous European hotel, legendary concierge Gustave H. and his protégé Zero become entangled in a madcap adventure involving a stolen Renaissance painting and a family fortune. Their journey weaves through quirky characters, eccentric humor, and a looming war, all told with Wes Anderson’s unique visual style.', '8.1', 'https://www.youtube.com/watch?v=1Fg5iWmQjwk', 'https://i.ytimg.com/vi/mXRztrOK47I/maxresdefault.jpg', 'R', 'true', 'false', 'https://m.media-amazon.com/images/I/713kiC-8JhL.jpg'), ('10', 'The Secret Life of Walter Mitty', 'A timid daydreamer, Walter Mitty, sets out on a real-life adventure across the globe to track down a missing photo negative for Life magazine’s final issue. Along the way, he transforms from a man lost in fantasies into someone who truly lives boldly.', '7.3', 'https://www.youtube.com/watch?v=QD6cy4PBQPI', 'https://i.ytimg.com/vi/XxuYQ1dQtJI/maxresdefault.jpg', 'PG', 'true', 'false', 'https://m.media-amazon.com/images/M/MV5BODYwNDYxNDk1Nl5BMl5BanBnXkFtZTgwOTAwMTk2MDE@._V1_FMjpg_UX1000_.jpg');